def minimum_total(triangle):
    n = len(triangle)
    dp = [[0]*n for _ in range(n)]
    dp[0][0] = triangle[0][0]
    for i in range(1, n):
        for j in range(i+1):
            best = min(
                dp[i-1][j-1] if j > 0 else 10**9,
                dp[i-1][j] if j < i else 10**9)
            dp[i][j] = triangle[i][j] + best
    return min(dp[-1])

